<script>
 import {onMount,onDestroy,tick} from 'svelte';import {LoaderCircle,AlertCircle} from 'lucide-svelte';import {studio} from '../studio.svelte';
 let {items=[]}=$props();let layer,badges=$state([]),module,host,frame=0,until=0,observer,resize;
 function measure(){frame=0;if(!layer||!module||module.classList.contains('collapsed')){badges=[];return;}const active=items.some(asset=>['running','queued','failed'].includes(asset.processingStatus));if(!active){badges=[];return;}const index=Math.max(0,items.findIndex(asset=>asset.id===studio.aid)),visible=items.filter((_,i)=>Math.abs(i-index)<=7),cards=[...module.querySelectorAll('.cf-card')],base=host.getBoundingClientRect();badges=cards.flatMap((card,i)=>{const asset=visible[i];if(!asset||!['running','queued','failed'].includes(asset.processingStatus))return [];const rect=card.getBoundingClientRect();return rect.width>0?[{id:asset.id,status:asset.processingStatus,x:rect.left-base.left+6,y:rect.top-base.top+6}]:[];});if(performance.now()<until)frame=requestAnimationFrame(measure);}
 function schedule(){until=performance.now()+650;if(!frame)frame=requestAnimationFrame(measure);}
 onMount(()=>{host=layer.parentElement;module=host.querySelector('.cf-root');observer=new MutationObserver(schedule);observer.observe(module,{subtree:true,attributes:true,attributeFilter:['style','class']});resize=new ResizeObserver(schedule);resize.observe(module);schedule();});
 $effect(()=>{items.map(asset=>[asset.id,asset.processingStatus]);studio.aid;void tick().then(schedule);});
 onDestroy(()=>{observer?.disconnect();resize?.disconnect();cancelAnimationFrame(frame);});
</script>
<div class="coverflow-status" bind:this={layer} aria-hidden="true">{#each badges as badge (badge.id)}<span class:failed={badge.status==='failed'} class="coverflow-status-badge" style:left={`${badge.x}px`} style:top={`${badge.y}px`} data-asset-id={badge.id}>{#if badge.status==='failed'}<AlertCircle size={14}/>{:else}<LoaderCircle size={14}/>{/if}</span>{/each}</div>
<style>.coverflow-status{position:absolute;inset:0;z-index:200;overflow:hidden;pointer-events:none}.coverflow-status-badge{position:absolute;display:flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:6px;background:var(--bg-elev);color:var(--accent);pointer-events:none;z-index:1}.coverflow-status-badge.failed{color:var(--danger)}.coverflow-status-badge:not(.failed) :global(svg){animation:cf-status-spin 1s linear infinite}@keyframes cf-status-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.coverflow-status-badge:not(.failed) :global(svg){animation:none}}</style>
